  value.Text="1.7";Call(f,"SaveProseProject");Call(f,"SetTextTargetUI",0.0);Call(f,"RestoreProseProject");Check(enabled.Checked&&value.Text=="1.7","Prose project restores its own target");Call(f,"LoadFile",srt);o=(RenderOptions)Call(f,"Options");Check(!enabled.Checked&&o.TargetSeconds==0,"Opening SRT clears TXT target and preserves source timeline mode");Call(f,"LoadFile",txt);Check(!enabled.Checked,"Opening another source does not inherit a prior target");
