  enabled.Checked=true;value.Text="invalid studio target";await (Task)Call(f,"ExportBatch");Check(jobs[0].State==JobState.Failed&&jobs.Skip(1).All(j=>j.State==JobState.Done),"Queue ignores invalid studio target and continues after one target overflow");Check(FinalAudio.PcmFrames(jobs[1].OutputPath)==40800&&FinalAudio.PcmFrames(jobs[3].OutputPath)==48000,"Queue exports requested TXT duration without leaking target to SRT");((TabControl)F(f,"tabs")).SelectedIndex=1;Capture(f,"txt-target-queue");Check(jobs.All(j=>File.Exists(j.ReportPath)),"Every attempted queue file retains its own report");
