  jobGrid.CurrentCell=jobGrid.Rows[1].Cells[6];var fill=new Timer{Interval=100};fill.Tick+=(a,b)=>{foreach(Form dialog in Application.OpenForms.Cast<Form>().Where(w=>w!=f&&w.Text.StartsWith("Thời lượng đích TXT")).ToArray()){Walk(dialog).OfType<TextBox>().First().Text="1.9";Walk(dialog).OfType<Button>().First(x=>x.Text=="Lưu đích cho file này").PerformClick();}};fill.Start();Call(f,"SetQueuedTextTarget");fill.Stop();fill.Dispose();Check(jobs[1].TargetSeconds==1.9,"Queue target dialog commits per-file duration");Call(f,"EditQueued");Check(enabled.Checked&&value.Text=="00:00:01,900","Editing queued TXT loads its target into Studio");enabled.Checked=false;Check(jobs[1].TargetSeconds==0,"Returning queued TXT to natural mode clears only its own target");Check(!(bool)F(f,"busy"),"GUI unlocked after target success, errors and queue operations");
  Console.WriteLine("TOTAL TXT TARGET UI "+count+" passed.");
